function validateQuestions() {
  for (const item of questions) {
    if (!item.topicId) throw new Error('Question missing topicId: ' + item.statement);
    if (!item.topicName) throw new Error('Question missing topicName: ' + item.statement);
    if (!item.statement) throw new Error('Question missing statement');
    const ids = item.answers.map((a) => a.id);
    const required = ['a', 'b', 'c', 'd'];
    for (const r of required) {
      if (!ids.includes(r)) throw new Error('Question missing answer id: ' + r + ' - '+ item.statement);
    }
    if (!required.includes(item.correctAnswerId)) {
      throw new Error('Invalid correctAnswerId: ' + item.correctAnswerId + ' - '+ item.statement);
    }
  }
}

async function seed() {
  validateQuestions();
  if (VALIDATE_ONLY) {
    console.log('✓ Validation OK: ' + questions.length + ' questions');
    process.exit(0);
  }

  console.log('Seeding questions...');
  const batch = db.batch();
  for (const item of questions) {
    const ref = db.collection('questions').doc();
    batch.set(ref, { ...item, createdAt: admin.firestore.FieldValue.serverTimestamp() });
  }
  await batch.commit();
  console.log('✓ ' + questions.length + ' questions written');
  console.log('Done!');
  process.exit(0);
}

seed().catch((e) => {
  console.error(e);
  process.exit(1);
});

